from google.cloud import pubsub_v1
import os

def publish_messages():
    # Publisher client for Google Cloud Pub/Sub
    publisher = pubsub_v1.PublisherClient()

    # Topic name (replace with your actual topic)
    topic_path = publisher.topic_path("your-project-id", "your-topic-name")

    # Batch of messages with attributes
    messages = [
        {
            "data": b"Hello, World!",
            "attributes": {"key1": "value1", "key2": "value2"}
        },
        {
            "data": b"Another message",
            "attributes": {"priority": "high", "type": "notification"}
        }
    ]

    # Publish messages
    futures = []
    for msg in messages:
        future = publisher.publish(
            topic_path,
            data=msg["data"],
            **msg["attributes"]
        )
        futures.append(future)

    # Wait for all messages to be published
    for future in futures:
        result = future.result(timeout=30)
        print(f"Published message with ID: {result}")

publish_messages()
